5. Programming a Brushless Motor

5.1. Arduino driving a hobby ESC
Because a PWM ESC speaks the same signal as a servo, the Servo library works. Always arm first (send minimum throttle) or the ESC will refuse to run.
#include &lt;Servo.h&gt;

Servo esc;

void setup() {
  esc.attach(9);              // ESC signal wire on D9
  esc.writeMicroseconds(1000); // arm: minimum throttle
  delay(3000);                 // wait for ESC arming beeps
}

void loop() {
  esc.writeMicroseconds(1300); // low throttle
  delay(2000);
  esc.writeMicroseconds(1600); // mid throttle
  delay(2000);
  esc.writeMicroseconds(1000); // stop
  delay(2000);
}


5.2. Raspberry Pi (Python) driving an ESC
from gpiozero import PWMOutputDevice
from time import sleep

# 50 Hz; duty as fraction of the 20 ms period.
esc = PWMOutputDevice(18, frequency=50)

def throttle(us):
    esc.value = us / 20000.0     # 1000 us -&gt; 0.05, 2000 us -&gt; 0.10

throttle(1000); sleep(3)         # arm
throttle(1400); sleep(2)         # spin up
throttle(1000)                   # stop


5.3. Closed-loop FOC (SimpleFOC style)
For precise torque/position control you drive the inverter directly with a FOC library and a position sensor. Conceptually:
#include &lt;SimpleFOC.h&gt;

BLDCMotor motor = BLDCMotor(11);                 // 11 pole pairs
BLDCDriver3PWM driver = BLDCDriver3PWM(9,10,11,8);
MagneticSensorI2C sensor = MagneticSensorI2C(AS5600_I2C);

void setup() {
  sensor.init();
  motor.linkSensor(&sensor);
  driver.voltage_power_supply = 12;
  driver.init();
  motor.linkDriver(&driver);
  motor.controller = MotionControlType::angle;   // position control
  motor.init();
  motor.initFOC();                                // align + calibrate
}

void loop() {
  motor.loopFOC();          // run the current/commutation loop
  motor.move(1.57);         // command target angle in radians
}
Here the code, not an ESC, computes commutation every cycle using the sensor angle. Industrial drives do the same internally and expose only a high-level target over EtherCAT/CANopen.

4. Programming a Hobby Servo

4.1. Arduino (Servo library)
The Servo library generates the 50 Hz pulse train for you; you just call write(angle).
#include &lt;Servo.h&gt;

Servo myServo;

void setup() {
  myServo.attach(9);            // signal pin D9
}

void loop() {
  myServo.write(0);             // go to 0 degrees
  delay(1000);
  myServo.write(90);            // center
  delay(1000);
  myServo.write(180);           // full travel
  delay(1000);

  // For fine control, command the raw pulse width in microseconds:
  myServo.writeMicroseconds(1500);   // ~center
  delay(1000);
}


4.2. Raspberry Pi (Python, gpiozero)
gpiozero maps a -1..+1 value onto the servo’s pulse range.
from gpiozero import Servo
from time import sleep

servo = Servo(17)   # BCM pin 17

servo.min()         # -1  -&gt; ~1.0 ms
sleep(1)
servo.mid()         #  0  -&gt; ~1.5 ms
sleep(1)
servo.max()         # +1  -&gt; ~2.0 ms
sleep(1)

servo.value = 0.25  # arbitrary position between -1 and 1
sleep(1)


4.3. ESP32 (MicroPython PWM)
Without a library, generate the pulse directly with a 50 Hz PWM channel and a 16-bit duty.
from machine import Pin, PWM

servo = PWM(Pin(13), freq=50)

def angle(deg):
    # 0 deg -&gt; 1.0 ms, 180 deg -&gt; 2.0 ms, 20 ms period
    us = 1000 + (deg / 180) * 1000
    duty = int(us / 20000 * 65535)   # fraction of period, 16-bit
    servo.duty_u16(duty)

angle(90)
Tip: Power servos from a separate 5-6V supply (not the MCU’s regulator) and tie grounds together; stall currents can brown out the controller.

📄 5. blink.c Example
#include "pico/stdlib.h"

int main() {
    const uint LED_PIN = 25;
    gpio_init(LED_PIN);
    gpio_set_dir(LED_PIN, GPIO_OUT);

    while (true) {
        gpio_put(LED_PIN, 1);
        sleep_ms(500);
        gpio_put(LED_PIN, 0);
        sleep_ms(500);
    }
}

5. Programming a Stepper

5.1. Arduino, raw STEP/DIR (A4988 / DRV8825)
#define STEP_PIN 3
#define DIR_PIN  4

void setup() {
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  digitalWrite(DIR_PIN, HIGH);       // pick a direction
}

void loop() {
  // 200 pulses = one full revolution at full step
  for (int i = 0; i &lt; 200; i++) {
    digitalWrite(STEP_PIN, HIGH);
    delayMicroseconds(800);          // shorter delay = faster
    digitalWrite(STEP_PIN, LOW);
    delayMicroseconds(800);
  }
  delay(1000);
}


5.2. Arduino with AccelStepper (accel/decel profiles)
Manual pulsing gives no acceleration; AccelStepper ramps speed so the motor does not stall or lose steps.
#include &lt;AccelStepper.h&gt;

AccelStepper stepper(AccelStepper::DRIVER, 3, 4);  // STEP=3, DIR=4

void setup() {
  stepper.setMaxSpeed(1000);        // steps/sec
  stepper.setAcceleration(500);     // steps/sec^2
  stepper.moveTo(2000);             // target position (absolute)
}

void loop() {
  if (stepper.distanceToGo() == 0)
    stepper.moveTo(-stepper.currentPosition());   // reverse
  stepper.run();                    // call often; steps as needed
}


5.3. Raspberry Pi (Python, RPi.GPIO)
import RPi.GPIO as GPIO
from time import sleep

STEP, DIR = 20, 21
GPIO.setmode(GPIO.BCM)
GPIO.setup([STEP, DIR], GPIO.OUT)

def move(steps, clockwise=True, delay=0.001):
    GPIO.output(DIR, clockwise)
    for _ in range(steps):
        GPIO.output(STEP, GPIO.HIGH)
        sleep(delay)
        GPIO.output(STEP, GPIO.LOW)
        sleep(delay)

move(200, clockwise=True)   # one revolution
GPIO.cleanup()


5.4. Silent driver (TMC2209)
TMC drivers add UART configuration, StealthChop (near-silent) and StallGuard (sensorless homing) on top of the same STEP/DIR interface, so the code above still works while you tune current/microsteps over serial.
